CREATE TABLE IF NOT EXISTS device_requests(hash TEXT PRIMARY KEY,user_code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS device_sessions(hash TEXT PRIMARY KEY,id TEXT UNIQUE NOT NULL,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,created_at TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS device_sessions_user ON device_sessions(user_id);
CREATE TABLE IF NOT EXISTS avatars(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,data TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_entitlements(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,call_limit INTEGER NOT NULL DEFAULT 0,used INTEGER NOT NULL DEFAULT 0,reserved INTEGER NOT NULL DEFAULT 0,expires INTEGER NOT NULL DEFAULT 0,subscription_id TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS ai_requests(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,status TEXT NOT NULL,created_at INTEGER NOT NULL,response TEXT,subscription_id TEXT);
CREATE INDEX IF NOT EXISTS ai_requests_user ON ai_requests(user_id,created_at);
